```js
import { unified } from "@astrojs/markdown-remark";
import { defineConfig } from "astro/config";
import { remarkModifiedTime } from "./remark-modified-time.mjs";

export default defineConfig({
  markdown: {
    processor: unified({
      remarkPlugins: [remarkModifiedTime],
    }),
  },
});
```

